        for v in row: counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]
    # A same-color diagonal pair is a line seed; extend that diagonal outward.
    for color in counts:
        if color == bg: continue
        pts = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == color]
        pairs = set()
        for r,c in pts:
            for dr,dc in ((1,1),(1,-1)):
                if 0 <= r+dr < h and 0 <= c+dc < w and grid[r+dr][c+dc] == color:
