 "content": "def transform(grid):
    # The demos establish diagonal ray extensions, but the test's two diagonal
    # marker runs are immediately blocked by other non-background cells. Preserve
    # all original cells and extend only through empty background cells.
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    positions = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                positions.setdefault(grid[r][c], set()).add((r,c))
    for color, pts in positions.items():
        for dr,dc in ((1,1),(1,-1)):
            for r,c in tuple(pts):
                if (r-dr,c-dc) in pts:
                    continue
                run=[]; rr,cc=r,c
                while (rr,cc) in pts:
                    run.append((rr,cc)); rr+=dr; cc+=dc
                if len(run)<2:
                    continue
                # Extend from both ends, stopping at the first occupied cell.
                for rr,cc,vr,vc in ((run[0][0]-dr,run[0][1]-dc,-dr,-dc), (run[-1][0]+dr,run[-1][1]+dc,dr,dc)):
                    while 0<=rr<h and 0<=cc<w and out[rr][cc]==bg:
                        out[rr][cc]=color
                        rr+=vr; cc+=vc
    return out
